/* R06 approved justice plaza: original XYZ surface, single motif, no slab. */
(function(root,factory){const api=factory();if(typeof module==='object')module.exports=api;else root.Plaza89=api;})(this,()=>{
let regions=[],holes=[];function prepare(cfg,earcut){const tri=p=>{const ix=earcut(p.flat()),ts=[];for(let i=0;i<ix.length;i+=3){const t=ix.slice(i,i+3).map(j=>p[j]);if((t[1][0]-t[0][0])*(t[2][1]-t[0][1])-(t[1][1]-t[0][1])*(t[2][0]-t[0][0])<0)t.reverse();ts.push(t);}return ts;};holes=cfg.holes.flatMap(tri);regions=[{p:cfg.polygon,kind:'plaza89'}].map(r=>({...r,masks:tri(r.p),box:[Math.min(...r.p.map(p=>p[0])),Math.min(...r.p.map(p=>p[1])),Math.max(...r.p.map(p=>p[0])),Math.max(...r.p.map(p=>p[1]))]}));}
function cut(vs,a,b){const d=v=>(b[0]-a[0])*(v[2]-a[1])-(b[1]-a[1])*(v[0]-a[0]),pos=[],neg=[];for(let i=0;i<vs.length;i++){const p=vs[i],q=vs[(i+1)%vs.length],dp=d(p),dq=d(q);if(dp>=0)pos.push(p);if(dp<=0)neg.push(p);if((dp<0&&dq>0)||(dp>0&&dq<0)){const t=dp/(dp-dq),r=p.map((x,j)=>x+(q[j]-x)*t);pos.push(r);neg.push(r);}}return[pos,neg];}
function split(vs,mask){let inner=vs,out=[];for(let k=0;k<3&&inner.length>=3;k++){const[a,b]=cut(inner,mask[k],mask[(k+1)%3]);if(b.length>=3)out.push(b);inner=a;}return{inner,out};}

function overlap(p,b){return !(p.every(v=>v[0]<b[0])||p.every(v=>v[0]>b[2])||p.every(v=>v[2]<b[1])||p.every(v=>v[2]>b[3]));}
function partition(pos,indices,kind){if(!regions.length)return [{pos,indices,kind}];let box=[Infinity,Infinity,-Infinity,-Infinity];for(let i=0;i<pos.length;i+=3){box[0]=Math.min(box[0],pos[i]);box[1]=Math.min(box[1],pos[i+2]);box[2]=Math.max(box[2],pos[i]);box[3]=Math.max(box[3],pos[i+2]);}if(!regions.some(r=>box[0]<=r.box[2]&&box[2]>=r.box[0]&&box[1]<=r.box[3]&&box[3]>=r.box[1]))return [{pos,indices,kind}];const groups=new Map(),put=(k,p)=>{if(!groups.has(k))groups.set(k,{pos:[],indices:[],kind:k});const g=groups.get(k);for(let i=1;i<p.length-1;i++){const a=p[0],b=p[i],c=p[i+1];if(Math.abs((b[0]-a[0])*(c[2]-a[2])-(b[2]-a[2])*(c[0]-a[0]))<1e-10)continue;const j=g.pos.length/3;g.pos.push(...a,...b,...c);g.indices.push(j,j+1,j+2);}};
for(let i=0;i<indices.length;i+=3){const tri=Array.from(indices.slice(i,i+3),j=>Array.from(pos.slice(j*3,j*3+3)));let rest=[tri];for(const r of regions){if(!overlap(tri,r.box)||r.onlyGrass&&!['grass','planting','soil','plaza','path'].includes(kind))continue;for(const mask of r.masks){const next=[];for(const p of rest){const q=split(p,mask);if(q.inner.length>=3){let fill=[q.inner];for(const h of holes){const nn=[];for(const f of fill){const c=split(f,h);if(c.inner.length>=3)put(kind,c.inner);nn.push(...c.out);}fill=nn;}for(const f of fill)put(r.kind,f);}next.push(...q.out);}rest=next;}}for(const p of rest)put(kind,p);}return [...groups.values()].filter(g=>g.indices.length);}

function uv(x,z){return[x/4,z/4];}
function material(B,scene){const m=new B.StandardMaterial('plaza89-stone',scene),t=new B.DynamicTexture('plaza89-stone-4m',256,scene,true),c=t.getContext();c.fillStyle='#bfc1b8';c.fillRect(0,0,256,256);c.strokeStyle='rgba(72,80,72,.13)';c.lineWidth=.7;for(let y=0;y<256;y+=32)for(let x=-(y/32%2)*24;x<256;x+=48)c.strokeRect(x,y,48,32);t.update();t.wrapU=t.wrapV=B.Texture.WRAP_ADDRESSMODE;t.anisotropicFilteringLevel=8;m.diffuseTexture=t;m.specularColor=B.Color3.Black();return m;}
return{prepare,partition,uv,material};});
